window.NPC_CHUNK_265 = [{"name":"Pallid Mask","cr":17,"xp":102400,"race":"aberration","gender":"Male","age_category":"Adult","alignment":"CE","size":"Medium","type":"aberration","sub_types":["chaotic","evil"],"init":9,"senses":["darkvision 60 ft."],"ac":30,"ac_touch":16,"ac_flat_footed":24,"ac_mods":"+5 Dex, +1 dodge, +14 natural","hp":275,"hd":"22d8+176","hd_value":22,"fort":16,"ref":14,"will":19,"defensive_abilities":["phantom of truth","rejuvenation"],"dr":"10/lawful","immunities":["critical hits","disease","mind-affecting effects","poison"],"resists":["acid 20","cold 20"],"sr":28,"speed":[{"type":"land","speed":30}],"melee":"+3 quarterstaff +24 (1d6+10) or reality leech +21 touch (1d6 Cha drain)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"horrific revelation","details":"DC 28"},{"type":"reality leech","details":"DC 28"},{"type":"sneak attack","details":"+6d6"}],"spell_like_abilities_caster_level":17,"spell_like_abilities_concentration":24,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"},{"spell":"detect thoughts"},{"spell":"tongues"}]},{"frequency":"at-will","spells":[{"spell":"confusion"},{"spell":"detect magic"},{"spell":"entropic shield"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"hideous laughter"}]},{"frequency":"1/day","spells":[{"spell":"phantasmal killer"},{"spell":"yellow sign","details":"Pathfinder Adventure Path #110 72"}]},{"frequency":"3/day","spells":[{"spell":"charm monster"},{"spell":"dimension door"},{"spell":"displacement"},{"spell":"greater dispel magic"},{"spell":"hold person"},{"spell":"mislead"},{"spell":"nondetection"}]}],"strength":20,"dexterity":21,"constitution":24,"intelligence":23,"wisdom":22,"charisma":25,"baseatk":16,"cmb":21,"cmd":37,"feats":[{"feat":"Combat Casting"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Greater Feint"},{"feat":"Improved Feint"},{"feat":"Improved Initiative"},{"feat":"Improved Lightning Reflexes"},{"feat":"Lightning Reflexes"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":19},{"skill":"Bluff","value":32},{"skill":"Diplomacy","value":32},{"skill":"Intimidate","value":32},{"skill":"Knowledge (arcana)","value":28},{"skill":"Knowledge (nobility)","value":31},{"skill":"Knowledge (planes, religion)","value":17},{"skill":"Perception","value":31},{"skill":"Sense Motive","value":31},{"skill":"Spellcraft","value":31},{"skill":"Use Magic Device","value":18}],"languages":["Common","Abyssal","Aklo","Celestial","Infernal","Undercommon","telepathy 100 ft."],"special_abilities":[{"type":"Herald of the Yellow King","kind":"Sp","details":"The Pallid Mask can use his yellow sign spell-like ability to inscribe the Yellow Sign on his own body. He can conceal this symbol within the folds of his robe, and reveal it once again as a move action. Creatures under the effect of a charm or compulsion spell cast by the Pallid Mask take a -4 penalty on their saving throws to resist the effects of the yellow sign."},{"type":"Horrific Revelation","kind":"Su","details":"As a swift action, the Pallid Mask can reveal a horrific truth to a single creature within 60 feet. The target must succeed at a DC 28 Will save or become confused and babble incoherently for 1 round as its mind reels at the terrible revelation. A creature that successfully saves against this ability is immune to this effect for 24 hours. This is a mind-affecting, language-dependent effect, and the save DC is Charisma-based."},{"type":"Phantom of Truth","kind":"Su","details":"The Pallid Mask's deceptions transcend truth and reality. He is immune to alignment-based spells and any spell or effect that would force him to tell the truth. Additionally, the Pallid Mask gains Bluff, Diplomacy, and Sense Motive as class skills."},{"type":"Reality Leech","kind":"Ex","details":"The Pallid Mask's touch steals the very essence of reality from his victims. Creatures struck by the Pallid Mask's touch attack take 1d6 points of Charisma drain and become less real, appearing faintly translucent and shadowy. Attacks from such creatures deal half their normal damage, and spells cast by an affected creature that don't deal damage have a 50% chance of affecting their targets. Creatures struck by the Pallid Mask remain unreal for 2d4 rounds. A successful DC 28 Will save negates the Charisma drain and reduces the duration of this effect to 1 round. A creature whose Charisma score is reduced to 0 by this effect dies and becomes permanently and entirely unreal. The creature functions in all ways as a permanent image (CL 15), and cannot be raised or resurrected until a wish, limited wish, or miracle spell is used to return its physical form. The illusory creature can continue to move and speak, but has no memory of its former life, and cannot travel farther than 30 ft. from the place it died."},{"type":"Rejuvenation","kind":"Su","details":"If killed in Carcosa, the Pallid Mask reforms in the parasitic city in 1d4 days."}],"gear":"+3 quarterstaff","source":"AP 114","unique_monster":1},{"name":"The Watcher In The Bay","cr":24,"xp":1228800,"race":"The Watcher In The Bay","age_category":"Adult","alignment":"CE","size":"Gargantuan","type":"aberration","sub_types":["aquatic"],"init":20,"senses":["all-around vision","darkvision 60 ft.","low-light vision","see in darkness","true seeing"],"auras":["unspeakable presence (300 ft., DC 33)"],"ac":42,"ac_touch":26,"ac_flat_footed":32,"ac_mods":"+10 Dex, +10 insight, +16 natural, -4 size","hp":518,"hd":"28d8+392","hd_value":28,"hp_mods":"fast healing 20","fort":23,"ref":21,"will":25,"defensive_abilities":["amorphous","insanity"],"dr":"10/epic and lawful","immunities":["ability damage","ability drain","aging","and petrification","cold","death effects","disease","energy drain","mind-affecting effects","paralysis"],"resists":["acid 30","sonic 30"],"sr":35,"speed":[{"type":"land","speed":50},{"type":"swim","speed":80}],"melee":"bite +29 (4d8+12 plus grab), 5 tentacles +29 (2d6+18/19-20 plus grab)","space":"20 ft.","reach":"20 ft. (40 ft. with tentacles)","special_attacks":[{"type":"constrict","details":"2d6+18"},{"type":"fast swallow"},{"type":"swallow whole","details":"1d8 Cha drain, AC 18, 51 hp"},{"type":"transformation"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":29,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"},{"spell":"nondetection"}]},{"frequency":"at-will","spells":[{"spell":"control plants"},{"spell":"control weather"},{"spell":"greater dispel magic"},{"spell":"hallucinatory terrain"},{"spell":"nightmare"}]},{"frequency":"1/day","spells":[{"spell":"tsunami"},{"spell":"vortex"}]},{"frequency":"3/day","spells":[{"spell":"demand"},{"spell":"quickened feeblemind"},{"spell":"quickened wall of thorns"}]}],"strength":34,"dexterity":30,"constitution":39,"intelligence":21,"wisdom":26,"charisma":29,"baseatk":21,"cmb":37,"cmb_special":"+39 bull rush, +41 grapple","cmd":67,"cmd_special":"69 vs. bull rush can't be tripped","feats":[{"feat":"Awesome Blow"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Greater Vital Strike"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (tentacle)"},{"feat":"Improved Vital Strike"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (feeblemind, wall of thorns)"},{"feat":"Skill Focus (Perception)"},{"feat":"Staggering Critical"},{"feat":"Vital Strike"}],"skills":[{"skill":"Escape Artist","value":41},{"skill":"Knowledge (arcana, nature, religion)","value":33},{"skill":"Perception","value":65},{"skill":"Spellcraft","value":36},{"skill":"Stealth","value":29},{"skill":"Swim","value":51},{"skill":"Use Magic Device","value":37}],"languages":["Aklo","Aquan","Sylvan; telepathy 200 ft."],"sq":["always watching","amphibious","compression","otherworldly insight","powerful tentacles"],"special_abilities":[{"type":"Always Watching","kind":"Ex","details":"The Watcher in the Bay has extraordinary vision, granting it a +20 bonus on Perception checks and the effects of true seeing at all times. This effect cannot be dispelled or suppressed. The Watcher can see into and out of water with perfect ease, and its vision is never impaired by water. It can see underwater as far as it can see on land, regardless of the water's level of obscurity. Water never provides cover from the Watcher in the Bay. As a free action, the Watcher can shift its vision to view the world through the eyes of any mutant created by its transformation ability, provided the mutant is within 10 miles of the Watcher. The Watcher in the Bay can determine the location of all mutants it has created within this 10-mile radius as if via status."},{"type":"Insanity","kind":"Ex","details":"Any creature that attempts to interact directly with the Watcher in the Bay's thoughts (such as via detect thoughts or telepathy) must succeed at a DC 33 Will save or be driven permanently insane (as per insanity, or the insanity rules on page 250 of the Pathfinder RPG GameMastery Guide, in which case this save DC is also the starting DC for the save to recover from the insanity). When the Watcher uses its telepathy to communicate with creatures, this ability doesn't activate unless the watcher focuses its mind on one opponent as a standard action. The save DC is Charisma-based."},{"type":"Otherworldly Insight","kind":"Ex","details":"The Watcher gains a +10 insight bonus on initiative checks and to its AC and CMD."},{"type":"Powerful Tentacles","kind":"Ex","details":"The Watcher's tentacles are a primary attack, and the Watcher adds 1-1/2 times its Strength bonus to damage rolls with the tentacles."},{"type":"Swallow Whole","kind":"Su","details":"A creature swallowed by the Watcher suffers Charisma drain. Each round the Watcher inflicts Charisma drain in this manner, it regains 5 hit points per point of Charisma drained. A creature drained to 0 Charisma is transformed."},{"type":"Transformation","kind":"Su","details":"When a swallowed creature is drained to 0 Charisma by the Watcher, it instantly transforms into a hideous, warped mockery of its previous form. The swallowed creature gains the mutant template (Pathfinder RPG Bestiary 5 180), and its alignment becomes chaotic evil. When a creature gains the template, all Charisma drain inflicted on the creature by the Watcher's swallow whole attack is healed. The Watcher can regurgitate a transformed mutant as an immediate action. A mutant created in this manner is free-willed, but regards the Watcher as its mother and obeys the Watcher's commands without question when they are given. These mutants are immune to the Watcher's unspeakable presence."},{"type":"Unspeakable Presence","kind":"Su","details":"The Watcher in the Bay emanates an aura that inflicts intense mental anguish and torment on all creatures within 300 ft. that can see and hear the Watcher. Any subjected creature must succeed at a DC 33 Will save or become staggered by this anguish for 1 round. A creature that successfully saves against the Watcher's unspeakable presence in 2 consecutive rounds is immune to the Watcher's unspeakable presence for 24 hours. The save DC is Charisma-based."}],"source":"AP 114"},{"name":"Imperial Infantry Troop","cr":9,"xp":6400,"race":"Imperial Infantry Troop","age_category":"Adult","alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human","troop"],"init":2,"ac":25,"ac_touch":12,"ac_flat_footed":23,"ac_mods":"+9 armor, +2 Dex, +4 natural","hp":126,"hd":"11d8+77","hd_value":11,"fort":13,"ref":7,"will":5,"defensive_abilities":["troop traits"],"speed":[{"type":"land","speed":30}],"melee":"troop (3d8+5)","space":"20 ft.","reach":"5 ft.","strength":20,"dexterity":15,"constitution":19,"intelligence":10,"wisdom":14,"charisma":13,"baseatk":8,"cmb":13,"cmb_special":"+15 bull rush and overrun","cmd":25,"feats":[{"feat":"Great Fortitude"},{"feat":"Greater Bull Rush"},{"feat":"Greater Overrun"},{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":19},{"skill":"Profession (soldier)","value":16}],"languages":["Common"],"sq":["elite troop","protect ally","united spirit"],"special_abilities":[{"type":"Elite Troop","kind":"Ex","details":"As a highly trained and well-equipped Molthuni unit, an imperial infantry troop gains an additional +4 natural armor bonus to its AC, increases the damage dice of its troop melee attack by one step, and gains 2 additional hit points per Hit Die. These effects are included in the troop's stat block."},{"type":"Protect Ally","kind":"Ex","details":"An imperial infantry troop provides soft cover to any creature it recognizes as an ally who shares its space. Such protected allies treat squares occupied by the troop as difficult terrain and must succeed at a concentration check (DC = 15 + spell level) to cast spells while so protected, but they don't take troop damage from being within the troop's space."},{"type":"United Spirit","kind":"Ex","details":"An imperial infantry troop is united by its dedication to its nation. When the troop takes damage that would reduce it to 0 or fewer hit points, it can attempt a Will saving throw (DC = 10 + the troop's number of negative hit points). On a success, the troop is instead reduced to 1 hp. The troop can benefit from this effect once every 24 hours."}],"source":"Lands Of Conflict"},{"name":"Imperial Archers Troop","cr":10,"xp":9600,"race":"Imperial Archers Troop","age_category":"Adult","alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human","troop"],"init":10,"ac":24,"ac_touch":16,"ac_flat_footed":18,"ac_mods":"+4 armor, +6 Dex, +4 natural","hp":114,"hd":"12d8+60","hd_value":12,"fort":13,"ref":12,"will":5,"defensive_abilities":["troop traits"],"speed":[{"type":"land","speed":30}],"melee":"troop (3d4+3)","space":"20 ft.","reach":"5 ft.","special_attacks":[{"type":"volley"}],"strength":17,"dexterity":22,"constitution":17,"intelligence":10,"wisdom":12,"charisma":13,"baseatk":9,"cmb":15,"cmd":28,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Reflexes"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":19},{"skill":"Profession (soldier)","value":16}],"languages":["Common"],"sq":["elite troop","united spirit"],"special_abilities":[{"type":"Elite Troop","kind":"Ex","details":"See the imperial infantry troop stat block on page 60. The additional die step of damage also applies to the troop's volley attack, as noted below."},{"type":"United Spirit","kind":"Ex","details":"See the imperial infantry troop stat block on page 60."},{"type":"Volley","kind":"Ex","details":"An imperial archers troop is trained and optimized for ranged combat. As a standard action, the troop can fire a volley of arrows. This attack takes the form of up to four lines with a distance of up to 100 ft. each. These lines can each start from any corner of any square in the troop's space, and the troop can accurately shoot over friendly creatures or large groups of individual creatures (though it cannot shoot over spaces smaller than a 10-foot-by-10-foot square). Each creature in any of these lines that isn't excluded in this way takes 4d8+3 points of piercing damage per line that hits it (Reflex DC 20 half). The save is Dexterity-based. The archers wield composite bows but are not accustomed to melee combat; this lowers the troop's AC by 2 and its troop melee damage by two die steps. These effects have already been calculated into the troop's stat block."}],"source":"Lands Of Conflict"},{"name":"Imperial Phalanx Troop","cr":11,"xp":12800,"race":"Imperial Phalanx Troop","age_category":"Adult","alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human","troop"],"init":0,"ac":28,"ac_touch":10,"ac_flat_footed":28,"ac_mods":"+9 armor, +5 shield, +4 natural","hp":150,"hd":"12d8+96","hd_value":12,"fort":14,"ref":4,"will":6,"save_mods":"+4 vs. trample","defensive_abilities":["troop traits"],"speed":[{"type":"land","speed":30}],"melee":"troop (3d8+8; 3d8+ 2d6 +8 vs. mounted opponents)","space":"20 ft.","reach":"10 ft.","strength":26,"dexterity":11,"constitution":19,"intelligence":10,"wisdom":14,"charisma":13,"baseatk":9,"cmb":17,"cmb_special":"+19 bull rush and overrun","cmd":27,"feats":[{"feat":"Great Fortitude"},{"feat":"Greater Bull Rush"},{"feat":"Greater Overrun"},{"feat":"Shield Focus"},{"feat":"Skill Focus (Intimidate, Perception)"}],"skills":[{"skill":"Intimidate","value":11},{"skill":"Perception","value":19},{"skill":"Profession (soldier)","value":11}],"languages":["Common"],"sq":["elite troop","phalanx troop","united spirit"],"special_abilities":[{"type":"Elite Troop","kind":"Ex","details":"See the imperial infantry troop stat block on page 60."},{"type":"Phalanx Troop","kind":"Ex","details":"An imperial phalanx troop is made up of a mixture of soldiers with polearms and those with blades and spears. This grants it an additional 5 ft. of reach with its troop melee attack. The troop also gains a +5 shield bonus to AC and a +4 bonus on saving throws against trample attacks, and its troop melee attack deals an additional 2d6 points of damage against mounted opponents. The troop gains 2 additional hit points per Hit Die. These effects are included in the troop's stat block."},{"type":"United Spirit","kind":"Ex","details":"See the imperial infantry troop stat block on page 60."}],"gear":"tower shield","source":"Lands Of Conflict"},{"name":"Nirmathi Skirmishers Troop","cr":8,"xp":4800,"race":"Nirmathi Skirmishers Troop","age_category":"Adult","alignment":"CG","size":"Medium","type":"humanoid","sub_types":["human","troop"],"init":8,"ac":21,"ac_touch":14,"ac_flat_footed":17,"ac_mods":"+7 armor, +4 Dex","hp":104,"hd":"11d8+50","hd_value":11,"fort":9,"ref":13,"will":7,"defensive_abilities":["troop traits"],"speed":[{"type":"land","speed":40}],"melee":"troop (2d6+5)","space":"20 ft.","reach":"5 ft.","special_attacks":[{"type":"skirmishers"}],"strength":20,"dexterity":19,"constitution":19,"intelligence":10,"wisdom":14,"charisma":13,"baseatk":8,"cmb":13,"cmd":27,"feats":[{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Knowledge (local, nature)","value":8},{"skill":"Perception","value":18},{"skill":"Stealth","value":6}],"languages":["Common"],"sq":["favored enemy","skirmishers"],"special_abilities":[{"type":"Favored Enemy","kind":"Ex","details":"Nirmathi skirmishers spend their training studying the techniques of their hated enemy, the Molthuni Imperial Army, and specifically learning how to defeat its troops in their Nirmathi homeland. This training and hatred grant the Nirmathi skirmishers troop a +2 bonus on Perception checks, troop melee damage, and damage rolls when facing Molthuni troop units. Their training also grants the Nirmathi skirmishers troop a +3 bonus on all Knowledge (local) and Knowledge (nature) checks. The bonuses on Knowledge checks are calculated into the troop's stat block."},{"type":"Skirmishers","kind":"Ex","details":"Nirmathi skirmishers are effective and versatile hit-and-run troops. This lowers the troop's AC by 2 and its troop melee damage by one die, but increases its movement by 10 ft. (these effects have already been calculated into the troop's stat block). Additionally, as a standard action, the troop can make a ranged attack similar to a volley. This attack can take the form of up to two lines starting from the corner of any square in the troop's space. This attack's range is 50 feet. All creatures in these lines take 3d6+5 points of piercing damage (Reflex DC 19 half). The save DC is Dexterity-based."}],"source":"Lands Of Conflict"},{"name":"Forest Guardians Troop","cr":10,"xp":9600,"race":"Forest Guardians Troop","age_category":"Adult","alignment":"CG","size":"Medium","type":"humanoid","sub_types":["human","troop"],"init":9,"ac":23,"ac_touch":16,"ac_flat_footed":17,"ac_mods":"+7 armor, +5 Dex, +1 dodge","hp":123,"hd":"13d8+65","hd_value":13,"fort":8,"ref":15,"will":8,"defensive_abilities":["troop traits"],"speed":[{"type":"land","speed":30}],"melee":"troop (3d6+4)","space":"20 ft.","reach":"5 ft.","special_attacks":[{"type":"volley"},{"type":"wild allies"}],"strength":18,"dexterity":21,"constitution":19,"intelligence":10,"wisdom":14,"charisma":13,"baseatk":9,"cmb":13,"cmd":29,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Handle Animal)"},{"feat":"Toughness"}],"skills":[{"skill":"Handle Animal","value":20},{"skill":"Knowledge (local)","value":5},{"skill":"Knowledge (nature)","value":6},{"skill":"Perception","value":10},{"skill":"Stealth","value":8}],"languages":["Common"],"sq":["favored enemy"],"special_abilities":[{"type":"Favored Enemy","kind":"Ex","details":"See the Nirmathi skirmishers troop stat block above. The bonus on damage rolls also applies to the forest guardians troop's volley attack."},{"type":"Volley","kind":"Ex","details":"A forest guardians troop can fire a volley of arrows as a standard action. This attack takes the form of up to four lines with a range of 100 feet. These lines can each start from the corner of any square in the troop's space. Each creature in any of these lines takes 3d6 points of piercing damage per line that hits it (Reflex DC 21 half). The save DC is Dexterity-based."},{"type":"Wild Allies","kind":"Ex","details":"A forest guardians troop is made up of individuals who have a tight connection to the forest and the creatures that inhabit it. As a standard action while in forest terrain, the troop's members can call upon their animal allies to frighten and harry enemy troops. If the forest guardians troop succeeds at a Handle Animal check with a DC equal to 10 + the enemy troop's Hit Dice + its Wisdom modifier, the enemy troop is shaken and its Armor Class (including touch and flat-footed AC) decreases by 2 for 1 round. For every 5 by which the check exceeds this DC, this effect lasts for 1 additional round. The forest guardians troop can use this ability only against enemy troops that they can see within 30 feet. Using this ability again on the same enemy troop, or using the Intimidate skill to demoralize the same enemy troop, simply extends the effect's duration (and doesn't create a stronger fear effect). The troop can use this ability against an enemy troop multiple times, but each subsequent check beyond the first increases the DC by 5. This increase resets after 1 hour has passed."}],"source":"Lands Of Conflict"},{"name":"Irgal's Axe Troop","cr":12,"xp":19200,"race":"Irgal's Axe Troop","age_category":"Adult","alignment":"CG","size":"Medium","type":"humanoid","sub_types":["human","troop"],"init":7,"ac":26,"ac_touch":14,"ac_flat_footed":22,"ac_mods":"+9 armor, +3 Dex, +1 dodge, +3 natural","hp":161,"hd":"17d8+85","hd_value":17,"fort":11,"ref":15,"will":9,"defensive_abilities":["evasion","troop traits"],"speed":[{"type":"land","speed":30}],"melee":"troop (4d6+6)","space":"20 ft.","reach":"5 ft.","special_attacks":[{"type":"volley"}],"strength":22,"dexterity":17,"constitution":19,"intelligence":10,"wisdom":14,"charisma":13,"baseatk":12,"cmb":18,"cmd":32,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Lunge"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Intimidate","value":11},{"skill":"Knowledge (local, nature)","value":4},{"skill":"Perception","value":22},{"skill":"Stealth","value":11}],"languages":["Common"],"sq":["favored enemy"],"special_abilities":[{"type":"Evasion","kind":"Ex","details":"Irgal's Axe troops are made up of scrappy and experienced fighters who can recognize when they're about to become the target of an area-of-effect ability and react accordingly. If the troop succeeds at a Reflex saving throw against an attack that normally deals half damage on a successful save, the troop instead takes no damage."},{"type":"Favored Enemy","kind":"Ex","details":"See the Nirmathi skirmishers troop stat block on page 62. The bonus on damage rolls also applies to the Irgal's Axe troop's volley attack."},{"type":"Volley","kind":"Ex","details":"An Irgal's Axe troop can fire a volley of arrows as a standard action. This attack takes the form of up to four lines with a range of 100 feet. These lines can each start from the corner of any square in the troop's space. Each creature in any of these lines takes 4d6 points of piercing damage per line that hits it (Reflex DC 21 half). The save DC is Dexterity-based."}],"source":"Lands Of Conflict"},{"name":"Wayang Brawler","cr":0.5,"xp":200,"race":"Wayang","age_category":"Adult","classes":[{"class":"brawler","level":1}],"alignment":"N","size":"Small","type":"humanoid","sub_types":["wayang"],"init":7,"senses":["darkvision 60 ft."],"ac":15,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+1 armor, +3 Dex, +1 size","hp":12,"hd":"1d10+2","hd_value":1,"fort":3,"ref":5,"will":0,"save_mods":"+2 vs. shadow spells","speed":[{"type":"land","speed":20}],"melee":"unarmed strike +4 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"martial flexibility","details":"4/day"}],"strength":15,"dexterity":16,"constitution":13,"intelligence":10,"wisdom":10,"charisma":10,"baseatk":1,"cmb":2,"cmd":15,"cmd_special":"17 vs. grapple","feats":[{"feat":"Improved Initiative"},{"feat":"Improved Unarmed Strike"}],"skills":[{"skill":"Acrobatics","value":7},{"skill":"Escape Artist","value":7},{"skill":"Intimidate","value":4},{"skill":"Perception","value":6},{"skill":"Stealth","value":9}],"languages":["Common","Minatan","Wayang"],"sq":["brawler's cunning","light and dark","martial training","shadow magic"],"gear":"haramaki","before_combat":"In the round before the start of the battle, two brawlers use martial flexibility to gain the benefits of Power Attack, while the remaining two use martial flexibility to gain the benefits of Improved Grapple.","during_combat":"In the first round, the two wayang brawlers with Power Attack move to flank the most armored PC. The remaining two attempt to grapple other PCs, preferring obvious spellcasters or those with large weapons. If the brawlers have trouble hitting, they use martial flexibility to gain the benefits of Weapon Focus (unarmed strike), and proceed to make lethal unarmed attacks.","morale":"While under the charm person effect, the wayang brawlers don't surrender. If the enchantment is somehow removed, the affected brawler immediately stops fighting.","source":"PFS 8-14, Pathfinder RPG Bestiary 4 274, Pathfinder RPG Advanced Class Guide 23"},{"name":"Wayang Gladiator","cr":2,"xp":600,"race":"Wayang","age_category":"Adult","classes":[{"class":"brawler","level":3}],"alignment":"N","size":"Small","type":"humanoid","sub_types":["wayang"],"init":7,"senses":["darkvision 60 ft."],"ac":17,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+3 armor, +3 Dex, +1 size","hp":33,"hd":"3d10+12","hd_value":3,"fort":6,"ref":6,"will":1,"save_mods":"+2 vs. shadow spells","speed":[{"type":"land","speed":20}],"melee":"unarmed strike +8 (1d4+3) or unarmed strike flurry of blows +6 (1d4+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"brawler's flurry"},{"type":"maneuver training","details":"grapple +1"},{"type":"martial flexibility","details":"4/day"}],"strength":15,"dexterity":16,"constitution":17,"intelligence":10,"wisdom":10,"charisma":10,"baseatk":3,"cmb":4,"cmb_special":"+7 grapple","cmd":17,"cmd_special":"20 vs. grapple","feats":[{"feat":"Improved Grapple"},{"feat":"Improved Initiative"},{"feat":"Improved Unarmed Strike"},{"feat":"Weapon Focus (unarmed strike)"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Escape Artist","value":9},{"skill":"Intimidate","value":6},{"skill":"Perception","value":8},{"skill":"Stealth","value":9}],"languages":["Common","Minatan","Wayang"],"sq":["brawler's cunning","light and dark","martial training","shadow magic"],"gear":"mwk studded leather, potion of bear's endurance, potion of magic fang","before_combat":"The wayang gladiators drink their potions of magic fang and portions of bear's endurance. They use their martial flexibility to gain the benefits of Power Attack in the round before combat commences.","during_combat":"Two of the wayang gladiators move to flank the PCs and make attacks combining flurry of blows and Power Attack. The remaining two split up and attempt to grapple obvious spellcasters or those with large weapons. If Power Attack fails to hit consistently or the gladiators are being struck too often, they use martial flexibility to gain the benefit of Dodge.","morale":"While under the charm person effect, the wayang gladiators don't surrender. If the enchantment is somehow removed, the affected gladiator immediately stops fighting.","base_statistics":"Without quaffing their potions of bear's endurance or potions of magic fang, the gladiators' statistics are hp 27; Fort +4; Melee unarmed strike +7 (1d4+2); Con 13.","source":"PFS 8-14, Pathfinder RPG Bestiary 4 274, Pathfinder RPG Advanced Class Guide 23"},{"name":"Eynemb","cr":3,"xp":800,"race":"wayang","gender":"Male","age_category":"Adult","classes":[{"class":"bard","level":4,"archetype":"shadow puppeteer"}],"alignment":"LE","size":"Small","type":"humanoid","sub_types":["wayang"],"init":2,"senses":["darkvision 60 ft."],"ac":14,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+1 armor, +2 Dex, +1 size","hp":25,"hd":"4d8+4","hd_value":4,"fort":1,"ref":6,"will":4,"save_mods":"+4 vs. bardic performance, language-dependent, and sonic+2 vs. shadow spells","speed":[{"type":"land","speed":20}],"melee":"rapier +3 (1d4-1/18-20)","ranged":"mwk shortbow +7 (1d4-1/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 13 rounds/day","details":"countersong, distraction, fascinate [DC 15], shadow puppets, shadow servant"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"ghost sound"},{"spell":"pass without trace"},{"spell":"ventriloquism"}]}],"spellsknown_caster":"bard","spellsknown_caster_level":4,"spellsknown_concentration":7,"spellsknown":[{"spell_level":2,"spell_slots":2,"spells":[{"spell":"mirror image"},{"spell":"misdirection"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"cause fear"},{"spell":"charm person"},{"spell":"lesser confusion"},{"spell":"silent image"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"light"},{"spell":"mage hand"},{"spell":"read magic"}]}],"strength":8,"dexterity":15,"constitution":10,"intelligence":16,"wisdom":10,"charisma":16,"baseatk":3,"cmb":1,"cmd":13,"feats":[{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"}],"skills":[{"skill":"Acrobatics","value":2},{"skill":"Bluff","value":10},{"skill":"Diplomacy","value":10},{"skill":"Intimidate","value":10},{"skill":"Knowledge (arcana)","value":12},{"skill":"Knowledge (planes)","value":12},{"skill":"Linguistics","value":8},{"skill":"Perception","value":9},{"skill":"Perform (act)","value":10},{"skill":"Perform (comedy)","value":8},{"skill":"Perform (oratory)","value":10},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":15}],"languages":["Common","Abyssal","Aklo","Infernal","Minatan","Shadowtongue","Wayang"],"sq":["bardic knowledge +2","light and dark","shadow magic","shadow play","versatile performance (oratory)"],"gear":"mwk shortbow with 20 arrows, rapier, bracers of armor +1, wand of charm person (CL 4th, 6 charges)","before_combat":"Eynemb casts mirror image on himself and uses his shadow puppets ability to summon a shadowy fiendish giant spider (DC 15 Will save to treat as 20% real) before interrupting the play.","during_combat":"While letting his giant spider do the fighting, Eynemb casts cause fear and lesser confusion on those PCs who seem like obvious fighters. He summons another giant spider when the first one is destroyed, and he otherwise tries to use the nearby rocks as cover from the PCs. He also calls the PCs the \"true puppets\" of the wayangs and their \"silly ritual.\"","morale":"Eynemb surrenders if reduced to 6 or fewer hit points, calling off his shadows in the process. It's unlikely the PCs have time to properly interrogate him, as after 3 rounds of combat, the ritual disruption creates a more pressing concern.","source":"PFS 8-14, Pathfinder RPG Bestiary 4 274, Pathfinder RPG Advanced Race Guide 210"},{"name":"Eynemb Subtier 4-5","cr":6,"xp":2400,"race":"wayang","gender":"Male","age_category":"Adult","classes":[{"class":"bard","level":7,"archetype":"shadow puppeteer"}],"alignment":"LE","size":"Small","type":"humanoid","sub_types":["wayang"],"init":6,"senses":["darkvision 60 ft."],"ac":16,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+2 armor, +1 deflection, +2 Dex, +1 size","hp":42,"hd":"7d8+7","hd_value":7,"fort":2,"ref":7,"will":5,"save_mods":"+4 vs. bardic performance, language-dependent, and sonic+2 vs. shadow spells","speed":[{"type":"land","speed":20}],"melee":"rapier +5 (1d4-1/18-20)","ranged":"mwk shortbow +10 (1d4-1/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 19 rounds/day","details":"move action; countersong, distraction, fascinate [DC 16], shadow puppets, shadow servant, suggestion [DC 16]"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"ghost sound"},{"spell":"pass without trace"},{"spell":"ventriloquism"}]}],"spellsknown_caster":"bard","spellsknown_caster_level":7,"spellsknown_concentration":10,"spellsknown":[{"spell_level":3,"spell_slots":2,"spells":[{"spell":"crushing despair"},{"spell":"major image"}]},{"spell_level":2,"spell_slots":4,"spells":[{"spell":"daze monster"},{"spell":"mirror image"},{"spell":"misdirection"},{"spell":"sound burst"}]},{"spell_level":1,"spell_slots":5,"spells":[{"spell":"cause fear"},{"spell":"charm person"},{"spell":"lesser confusion"},{"spell":"silent image"},{"spell":"ventriloquism"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"light"},{"spell":"mage hand"},{"spell":"read magic"}]}],"strength":8,"dexterity":15,"constitution":10,"intelligence":16,"wisdom":10,"charisma":16,"baseatk":5,"cmb":3,"cmd":16,"feats":[{"feat":"Improved Initiative"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Weapon Focus (shortbow)"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Bluff","value":13},{"skill":"Diplomacy","value":13},{"skill":"Disguise","value":13},{"skill":"Intimidate","value":13},{"skill":"Knowledge (arcana)","value":16},{"skill":"Knowledge (planes)","value":16},{"skill":"Linguistics","value":9},{"skill":"Perception","value":12},{"skill":"Perform (act)","value":13},{"skill":"Perform (comedy)","value":10},{"skill":"Perform (oratory)","value":13},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":18}],"languages":["Common","Abyssal","Aklo","Gnome","Infernal","Minatan","Shadowtongue","Wayang"],"sq":["bardic knowledge +3","light and dark","lore master 1/day","shadow magic","shadow play","versatile performances (act, oratory)"],"gear":"mwk shortbow, rapier, bracers of armor +2, ring of protection +1, 20 arrows, wand of charm person (CL 7th, 8 charges)","before_combat":"Eynemb casts mirror image on himself and uses his shadow puppets ability to summon a shadowy fiendish constrictor snake (DC 16 Will save to treat as 20% real) before interrupting the festival.","during_combat":"While letting his giant snake do the fighting, Eynemb casts crushing despair and daze monster on those  PCs who seem like obvious fighters. He summons another constrictor snake when the first one is destroyed, and he otherwise tries to use the nearby rocks as cover from the PCs. He also calls the PCs the \"true puppets\" of the wayangs and their \"silly ritual.\"","morale":"Eynemb surrenders if reduced to 12 or fewer hit points, calling off his shadows in the process. It's unlikely the PCs have time to properly interrogate him, as after 3 rounds of combat, the ritual disruption creates a more pressing concern.","source":"PFS 8-14, Pathfinder RPG Bestiary 4 274, Pathfinder RPG Advanced Race Guide 210"},{"name":"Shadow Dire Wolf","cr":4,"xp":1200,"race":"Shadow Dire Wolf","age_category":"Adult","alignment":"NE","size":"Large","type":"outsider","sub_types":["augmented animal"],"init":2,"senses":["darkvision 60 ft.","low-light vision","scent"],"ac":14,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+2 Dex, +3 natural, -1 size","hp":37,"hd":"5d8+15","hd_value":5,"fort":7,"ref":6,"will":2,"defensive_abilities":["shadow blend"],"dr":"5/magic","resists":["cold 10","electricity 10"],"sr":9,"speed":[{"type":"land","speed":50}],"melee":"bite +7 (1d8+6 plus trip)","space":"10 ft.","reach":"5 ft.","strength":19,"dexterity":15,"constitution":17,"intelligence":2,"wisdom":12,"charisma":10,"baseatk":3,"cmb":8,"cmd":20,"cmd_special":"24 vs. trip","feats":[{"feat":"Run"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Perception","value":10},{"skill":"Stealth","value":3},{"skill":"Survival","value":1,"special":"+4 scent tracking"}],"special_abilities":[{"type":"Shadow Blend","kind":"Su","details":"In any illumination other than bright light, a shadow creature blends into the shadows, giving it concealment (20% miss chance). The shadow dire wolf can suspend or resume this ability as a free action."}],"during_combat":"The shadow dire wolf sticks to the shadows, biting and tripping any foes it can get close to.","morale":"If half or more of the PCs are unconscious or dying, the shadow dire wolf flees into the night.","source":"PFS 8-14"},{"name":"Shadow Girallon","cr":7,"xp":3200,"race":"Shadow Girallon","age_category":"Adult","alignment":"NE","size":"Large","type":"outsider","sub_types":["augmented magical beast"],"init":7,"senses":["darkvision 60 ft.","low-light vision","scent"],"ac":18,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+3 Dex, +6 natural, -1 size","hp":73,"hd":"7d10+35","hd_value":7,"fort":9,"ref":8,"will":5,"defensive_abilities":["shadow blend"],"dr":"5/magic","resists":["cold 10","electricity 10"],"sr":12,"speed":[{"type":"climb","speed":40},{"type":"land","speed":40}],"melee":"bite +10 (1d6+4), 4 claws +10 (1d4+4 plus rend)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rend","details":"4 claws, 1d4+6"}],"strength":19,"dexterity":17,"constitution":18,"intelligence":2,"wisdom":12,"charisma":7,"baseatk":7,"cmb":12,"cmd":25,"feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":12},{"skill":"Perception","value":11},{"skill":"Stealth","value":5}],"special_abilities":[{"type":"Shadow Blend","kind":"Su","details":"In any illumination other than bright light, a shadow creature blends into the shadows, giving it concealment (20% miss chance). The shadow dire wolf can suspend or resume this ability as a free action."}],"during_combat":"The shadow girallon focuses on a single foe at a time, attempting to rend his flesh.","morale":"If half or more of the PCs are unconscious or dying, the shadow girallon flees into the night.","source":"PFS 8-14"},{"name":"Leng Mummy","cr":9,"xp":6400,"race":"denizen of leng","age_category":"Adult","alignment":"CE","size":"Medium","type":"undead","sub_types":["augmented outsider","extraplanar"],"templates_applied":"mummified","init":4,"senses":["darkvision 60 ft."],"auras":["frightful presence (30 ft., DC 20, 1d6 rounds)"],"ac":25,"ac_touch":15,"ac_flat_footed":20,"ac_mods":"+4 Dex, +1 dodge, +10 natural","hp":115,"hd":"10d8+60","hd_value":10,"fort":12,"ref":11,"will":6,"defensive_abilities":["unusual anatomy"],"dr":"5/-","immunities":["undead traits"],"resists":["cold 30","electricity 30"],"sr":19,"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":30}],"melee":"bite +15 (1d8+4 plus 1d6 Dex drain), 2 claws +14 (1d6+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"burst of vengeance"},{"type":"dust stroke"},{"type":"sneak attack","details":"+3d6"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"tongues"}]},{"frequency":"1/day","spells":[{"spell":"locate object"}]},{"frequency":"3/day","spells":[{"spell":"detect thoughts"},{"spell":"hypnotic pattern"},{"spell":"levitate"},{"spell":"minor image"}]}],"strength":18,"dexterity":18,"intelligence":16,"wisdom":17,"charisma":21,"baseatk":10,"cmb":14,"cmd":29,"feats":[{"feat":"Deceitful"},{"feat":"Dodge"},{"feat":"Improved Natural Attack (bite, claws)"},{"feat":"Mobility"},{"feat":"Persuasive"},{"feat":"Spring Attack"},{"feat":"Toughness"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Bluff","value":21},{"skill":"Diplomacy","value":7},{"skill":"Disable Device","value":12},{"skill":"Disguise","value":12,"special":"+4 when disguised as a Medium humanoid"},{"skill":"Intimidate","value":11},{"skill":"Knowledge (arcana)","value":15},{"skill":"Perception","value":15},{"skill":"Profession (sailor)","value":8},{"skill":"Sense Motive","value":15},{"skill":"Sleight of Hand","value":16},{"skill":"Spellcraft","value":10},{"skill":"Stealth","value":20},{"skill":"Use Magic Device","value":16}],"languages":["Aklo; tongues"],"sq":["no breath"],"special_abilities":[{"type":"Burst of Vengeance","kind":"Su","details":"Despite its slow, lumbering nature, a Leng mummy is capable of lurching forward to attack with a short but surprising explosion of speed. Twice per day as a swift action, a Leng mummy may act as if affected by a haste spell for 1 round."},{"type":"Dexterity Drain","kind":"Su","details":"The otherworldly teeth and tongues of a Leng mummy deal 1d6 points of Dexterity drain with a bite. Constructs, elementals, and other creatures that don't possess flesh are immune to this effect. A successful DC 20 Fortitude save reduces the Dexterity drain to 1 point. The save DC is Charisma-based."},{"type":"Dust Stroke","kind":"Su","details":"A creature killed by a Leng mummy's natural attack disintegrates into a cloud of dust and ash, completely destroying the victim's body (as per disintegrate)."},{"type":"Site-Bound","kind":"Su","details":"A Leng mummy is bound to the site in which it was created and loses its planar fast healing ability and its plane shift spell-like ability. This also hampers its sneak attack damage, reducing it to 3d6."},{"type":"Unusual Anatomy","kind":"Ex","details":"Each Leng mummy's internal anatomy is different, and it has a 50% chance to treat any critical hit or sneak attack against it as a normal hit."},{"type":"Vulnerability","kind":"Su","details":"The mummification process leaves a Leng mummy vulnerable to fire. As a fail-safe in case of rebellion, a mummified creature is subtly marked during the ritual process with a hieroglyph someplace inconspicuous on its body or wrappings that identifies the particular energy type to which it is vulnerable. A successful DC 20 Perception check is needed to find the mark but a successful DC 25 Linguistics check is still required to decipher the hieroglyph's meaning."}],"before_combat":"When the mummies detect anyone approaching-such as a creature manipulating the trap door above the center of the room, one of the mummies uses minor image to create an image of Hrethnar Olvaradsson, a powerfully built, golden-haired Ulfen man wearing midnight blue robes, seated on the enormous stone throne.","during_combat":"One round after the first PC reaches the floor of  this room, the mummies attack. During the first two rounds of combat they use their burst of vengeance ability to gain an extra bite attack. Thereafter, the mummies use Spring Attack to dart in and out of melee, striking at a different PC each round with a bite attack.","morale":"The mummies fight until destroyed. They pursue fleeing PCs, but they don't leave areas B3, B4a, and B4b.","source":"PFS 8-15, Pathfinder RPG Bestiary 4 196, Pathfinder RPG Bestiary 2 82"},{"name":"Hrethnar Olvaradsson","cr":6,"xp":2400,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"evoker","level":7},{"class":"fighter","level":7}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":-3,"ac":14,"ac_touch":10,"ac_flat_footed":14,"ac_mods":"+4 armor","hp":109,"hd":"7d6+7d10+42","hd_value":14,"fort":4,"ref":-1,"will":3,"save_mods":"Will: +2 vs. fear","weaknesses":["negative levels","weakened"],"speed":[{"type":"land","speed":30}],"melee":"unarmed strike +7 (1d3+4 nonlethal)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"intense spells","details":"+3 damage"},{"type":"weapon training","details":"axes +1"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"6/day","spells":[{"spell":"force missile","details":"1d4+3"}]}],"spellsprepared_caster":"evoker","spellsprepared_caster_level":7,"spellsprepared_concentration":10,"spellsprepared":[{"spell_level":1,"spell_slots":7,"spells":[{"spell":"mage armor","count":4},{"spell":"shocking grasp","count":3}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"}]}],"prohibited_schools":"Divination, Enchantment","strength":18,"dexterity":10,"constitution":18,"intelligence":16,"wisdom":12,"charisma":15,"baseatk":10,"cmb":7,"cmd":17,"feats":[{"feat":"Arcane Strike"},{"feat":"Craft Wondrous Item"},{"feat":"Improved Critical (battleaxe)"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Scribe Scroll"},{"feat":"Spell Mastery"},{"feat":"Step Up"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (battleaxe)"},{"feat":"Weapon Specialization (battleaxe)"}],"skills":[{"skill":"Bluff","value":0},{"skill":"Craft (alchemy)","value":8},{"skill":"Intimidate","value":3},{"skill":"Knowledge (arcana)","value":9},{"skill":"Knowledge (geography)","value":3},{"skill":"Knowledge (history)","value":5},{"skill":"Knowledge (nature)","value":3},{"skill":"Knowledge (planes)","value":8},{"skill":"Perception","value":1},{"skill":"Sense Motive","value":1},{"skill":"Spellcraft","value":8},{"skill":"Survival","value":3},{"skill":"Swim","value":3}],"languages":["Common","Aklo","Polyglot","Skald","Varisian"],"sq":["arcane bond (ring of counterspells)","armor training 2","immortal"],"special_abilities":[{"type":"Immortal","kind":"Su","details":"While imprisoned aboard the Voracious, Hrethnar doesn't age, nor does he require food or water to sustain him. If removed from the Voracious, he begins to age normally. If taken more than 1 mile from the Gloomspires, his lost years catch up to him and he instantly dies."},{"type":"Negative Levels","kind":"Su","details":"Hrethnar's life force has slowly drained away during his long imprisonment. He currently has 7 negative levels that can't be removed until he is removed from the Voracious. The effects of these negative levels have already been calculated into his stat block."},{"type":"Weakened","kind":"Ex","details":"Hrethnar doesn't have access to his spellbook. Without his spellbook, Hrethnar can only recall and cast the spells associated with his Spell Mastery feat (detect magic, mage armor, and shocking grasp). He is also unarmed."}],"gear":"ring of counterspells (contains dominate person)","before_combat":"Hrethnar casts mage armor on himself.","during_combat":"Hrethnar casts his offensive spells and uses his force missile spell-like ability. After these abilities are exhausted, he dares his enemies to toss him an axe so he can take his foes with him into death.","morale":"Hrethnar is haughty and proud. He fights to the death.","source":"PFS 8-15"},{"name":"Tukang, Grenadier Trainee","cr":1,"xp":400,"race":"hobgoblin","gender":"Male","age_category":"Adult","classes":[{"class":"alchemist","level":2}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["goblinoid"],"init":3,"senses":["darkvision 60 ft."],"ac":15,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+2 armor, +3 Dex","hp":18,"hd":"2d8+6","hd_value":2,"fort":5,"ref":6,"will":2,"save_mods":"+2 bonus vs. poison","speed":[{"type":"land","speed":30}],"melee":"heavy mace +2 (1d8+1)","ranged":"bomb +5 (1d6+2 fire) or dagger +4 (1d4+1/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bomb","details":"4/day, 1d6+2 fire, DC 13"}],"extractsprepared_caster":"alchemist","extractsprepared_caster_level":2,"extractsprepared":[{"spell_level":1,"spells":[{"spell":"bomber's eye"},{"spell":"cure light wounds"},{"spell":"true strike"}]}],"strength":12,"dexterity":16,"constitution":15,"intelligence":15,"wisdom":10,"charisma":8,"baseatk":1,"cmb":2,"cmd":15,"feats":[{"feat":"Brew Potion"},{"feat":"Iron Will"},{"feat":"Throw Anything"}],"skills":[{"skill":"Craft (alchemy)","value":7},{"skill":"Heal","value":7},{"skill":"Knowledge (arcana)","value":6},{"skill":"Perception","value":5},{"skill":"Spellcraft","value":7},{"skill":"Stealth","value":11},{"skill":"Survival","value":5}],"languages":["Common","Dwarven","Giant","Goblin"],"sq":["alchemy (alchemy crafting +2)","discovery (precise bombs [2 squares])","mutagen (+4/-2, +2 natural armor, 20 minutes)","poison use"],"gear":"leather armor, daggers (3), heavy mace, hooded lantern, Provision Points (3), 16 gp, potion of cure light wounds (2), potion of invisibility, alchemist's fire (3), antitoxin, healer's kit, oil (5), smokestick (2), tanglefoot bag (2), thunderstone (2)","before_combat":"Ironfang grenadiers usually drink a bomber's eye infusion just before battle, but Tukang's has already expired.","during_combat":"Grenadier trainees begin their assaults with their bombs, and drink a strength mutagen if opponents close to melee with them.","morale":"Ironfang troops fight to the death.","source":"AP 115, Pathfinder RPG Bestiary 175, Pathfinder RPG Advanced Player's Guide 26"},{"name":"Semfet, Ironfang Scout","cr":1,"xp":400,"race":"hobgoblin","gender":"Female","age_category":"Adult","classes":[{"class":"ranger","level":2}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["goblinoid"],"init":3,"senses":["darkvision 60 ft."],"ac":14,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+1 armor, +3 Dex","hp":19,"hd":"2d10+4","hd_value":2,"fort":4,"ref":6,"will":1,"speed":[{"type":"land","speed":30}],"melee":"mwk battleaxe +3 (1d8+2/x3), handaxe +2 (1d6+1/x3)","ranged":"composite longbow +5 (1d8+2/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"combat style","details":"two-weapon combat"},{"type":"favored enemy","details":"animals +2"}],"strength":15,"dexterity":16,"constitution":12,"intelligence":12,"wisdom":13,"charisma":8,"baseatk":2,"cmb":4,"cmd":17,"feats":[{"feat":"Point-Blank Shot"},{"feat":"Two-Weapon Fighting"}],"skills":[{"skill":"Climb","value":7},{"skill":"Intimidate","value":3},{"skill":"Knowledge (nature)","value":6},{"skill":"Perception","value":6},{"skill":"Ride","value":8},{"skill":"Stealth","value":11},{"skill":"Survival","value":6},{"skill":"Swim","value":7}],"languages":["Common","Dwarven","Goblin"],"sq":["track +1","wild empathy +1"],"gear":"padded armor, composite longbow (+2 Str) with 20 arrows, handaxe, mwk battleaxe, backpack, bedroll, blanket, mess kit, small tent, Provision Points (3), 3 gp, potion of cure light wounds (2), alchemist's fire (2)","before_combat":"If the PCs make a lot of noise battling the wolf in area C1, Semfet draws her longbow and readies to fire at the first creature that enters the temple.","during_combat":"Semfet puts her back to the altar to discourage flankers.","morale":"Ironfang soldiers fight to the death.","source":"AP 115, Pathfinder RPG Bestiary 175"},{"name":"Kergri, Ironfang Heavy Trooper","cr":2,"xp":600,"race":"Hobgoblin","age_category":"Adult","classes":[{"class":"fighter","level":3}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["goblinoid"],"init":6,"senses":["darkvision 60 ft."],"ac":19,"ac_touch":12,"ac_flat_footed":17,"ac_mods":"+6 armor, +2 Dex, +1 shield","hp":27,"hd":"3d10+6","hd_value":3,"fort":5,"ref":3,"will":3,"save_mods":"Will: +1 vs. fear","speed":[{"type":"land","speed":30}],"melee":"mwk cold iron scimitar +6 (1d6+2/18-20)","ranged":"mwk light crossbow +6 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":14,"constitution":15,"intelligence":10,"wisdom":14,"charisma":8,"baseatk":3,"cmb":5,"cmd":17,"feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Point-Blank Shot"},{"feat":"Rapid Reload"}],"skills":[{"skill":"Handle Animal","value":4},{"skill":"Intimidate","value":4},{"skill":"Perception","value":4},{"skill":"Stealth","value":8},{"skill":"Survival","value":7}],"languages":["Common","Goblin"],"sq":["armor training 1"],"gear":"mwk breastplate, mwk buckler, dagger, mwk cold iron scimitar, mwk light crossbow with 20 bolts, animal harness, backpack, bedroll, compass, crowbar, manacles, Provision Points (4), signal whistle, silk rope (50 ft.), small tent, 16 gp, potion of cure light wounds (3), potion of endure elements, alchemist's fire (2), antiplague, antitoxin, scent cloak (3)","during_combat":"Kergri releases Kur to attack, then peppers intruders with her crossbow and alchemist's fire from the center of the bridge until they either close with her or take cover, at which point she draws her scimitar.","morale":"Like most Ironfang troops, Kergri fights to the death.","source":"AP 115, Pathfinder RPG Bestiary 175"},{"name":"Shalra","cr":3,"xp":800,"race":"Hobgoblin","age_category":"Adult","classes":[{"class":"rogue","level":4}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["goblinoid"],"init":3,"senses":["darkvision 60 ft."],"ac":16,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+3 armor, +3 Dex","hp":33,"hd":"4d8+12","hd_value":4,"fort":3,"ref":7,"will":1,"defensive_abilities":["evasion","trap sense +1","uncanny dodge"],"speed":[{"type":"land","speed":30}],"melee":"+1 dagger +7 (1d4+3/19-20)","ranged":"shortbow +6 (1d6/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack +2d6 plus 2 bleed"}],"strength":14,"dexterity":17,"constitution":14,"intelligence":14,"wisdom":10,"charisma":8,"baseatk":3,"cmb":5,"cmd":18,"feats":[{"feat":"Combat Reflexes"},{"feat":"Skill Focus (Survival)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Bluff","value":6},{"skill":"Disable Device","value":12},{"skill":"Escape Artist","value":10},{"skill":"Intimidate","value":6},{"skill":"Perception","value":7},{"skill":"Sense Motive","value":7},{"skill":"Sleight of Hand","value":10},{"skill":"Stealth","value":14},{"skill":"Survival","value":7}],"languages":["Common","Draconic","Giant","Goblin"],"sq":["rogue talents (bleeding attack +2, combat trick)","trapfinding +2"],"gear":"mwk studded leather, +1 dagger, shortbow with 20 arrows, 96 sp, oil of darkness, potion of cat's grace (2)","during_combat":"Shalra attempts a coup de grace against sleeping or helpless foes. Should the encounter become a fight, she uses her oil of darkness on a silver piece, then uses hit-and-run tactics to inflict bleeding attacks before falling back. If confronted or pursued by multiple foes, she drinks a potion of cat's grace.","morale":"When Shalra drops beneath 10 hit points, she tries to escape by using the magically created darkness or bluffing to create a distraction. She'd rather receive a minor reward for locating the fugitives than die in a fool's fight.","source":"AP 115, Pathfinder RPG Bestiary 175"}];
